348→/* ===========================================
349→   VIEW TRANSITIONS - Cinematic Page Crossfades
350→   =========================================== */
351→
352→/*
353→ * Design philosophy:
354→ * - Film dissolve feel, not flashy web animation
355→ * - Content: subtle crossfade with micro-scale for depth
356→ * - Navigation: fade only (no scale/position change - stays anchored)
357→ * - Duration: 500ms content, 400ms nav (slow enough to feel intentional)
358→ * - Easing: ease-in-out for cinematic linear-ish blend
359→ */
360→
361→/* Dark canvas behind all transition layers — prevents white bleed-through */
362→::view-transition {
363→  background-color: #141414;
364→}
365→
366→::view-transition-group(root),
367→::view-transition-group(navigation),
368→::view-transition-group(footer) {
369→  background-color: #141414;
370→}
371→
372→/* Root (main content) transition */
373→::view-transition-old(root),
374→::view-transition-new(root) {
375→  animation-duration: 500ms;
376→  animation-timing-function: ease-in-out;
377→}
378→
379→/* Old page: fade out with slight scale down */
380→::view-transition-old(root) {
381→  animation-name: fade-and-scale-out;
382→}
383→
384→/* New page: fade in with slight scale up */
385→::view-transition-new(root) {
386→  animation-name: fade-and-scale-in;
387→}
388→
389→@keyframes fade-and-scale-out {
390→  from {
391→    opacity: 1;
392→    transform: scale(1);
393→  }
394→  to {
395→    opacity: 0;
396→    transform: scale(0.98);
397→  }
398→}
399→
400→@keyframes fade-and-scale-in {
401→  from {
402→    opacity: 0;
403→    transform: scale(1.02);
404→  }
405→  to {
406→    opacity: 1;
407→    transform: scale(1);
408→  }
409→}
410→
411→/* Navigation: fade only, no scale (stays anchored) */
412→::view-transition-old(navigation),
413→::view-transition-new(navigation) {
414→  animation-duration: 400ms;
415→  animation-timing-function: ease-in-out;
416→}
417→
418→::view-transition-old(navigation) {
419→  animation-name: fade-out-only;
420→}
421→
422→::view-transition-new(navigation) {
423→  animation-name: fade-in-only;
424→}
425→
426→/* Hero reel: fade only, no scale (prevents white flash from iframe reinit) */
427→/* Dark background on the transition group prevents white bleed-through during crossfade */
428→::view-transition-group(hero-reel) {
429→  background-color: #141414;
430→}
431→
432→::view-transition-old(hero-reel),
433→::view-transition-new(hero-reel) {
434→  animation-duration: 400ms;
435→  animation-timing-function: ease-in-out;
436→}
437→
438→::view-transition-old(hero-reel) {
439→  animation-name: fade-out-only;
440→}
441→
442→::view-transition-new(hero-reel) {
443→  animation-name: fade-in-only;
444→}
445→
446→/* Footer: fade only, no scale (stays anchored) */
447→::view-transition-old(footer),
448→::view-transition-new(footer) {
449→  animation-duration: 400ms;
450→  animation-timing-function: ease-in-out;
451→}
452→
453→::view-transition-old(footer) {
454→  animation-name: fade-out-only;
455→}
456→
457→::view-transition-new(footer) {
458→  animation-name: fade-in-only;
459→}
460→
461→@keyframes fade-out-only {
462→  from { opacity: 1; }
463→  to { opacity: 0; }
464→}
465→
466→@keyframes fade-in-only {
467→  from { opacity: 0; }
468→  to { opacity: 1; }
469→}
470→
471→/* Respect reduced motion */
472→@media (prefers-reduced-motion: reduce) {
473→  ::view-transition-old(root),
474→  ::view-transition-new(root),
475→  ::view-transition-old(navigation),
476→  ::view-transition-new(navigation),
477→  ::view-transition-old(hero-reel),
478→  ::view-transition-new(hero-reel),
479→  ::view-transition-old(footer),
480→  ::view-transition-new(footer) {
481→    animation: none !important;
482→  }
483→}
