39→/**
40→ * Render markdown-style text as React nodes (no dangerouslySetInnerHTML).
41→ * Supports: **bold**, *italic*, `code`
42→ */
43→function renderFormattedText(text: string): React.ReactNode {
44→  // Tokenize: split on bold, code, and italic markers
45→  const tokenRegex = /(\*\*(.+?)\*\*|`(.+?)`|(?<!\*)\*(?!\*)(.+?)(?<!\*)\*(?!\*))/g;
46→  const nodes: React.ReactNode[] = [];
47→  let lastIndex = 0;
48→  let key = 0;
49→  let match: RegExpExecArray | null;
50→
51→  while ((match = tokenRegex.exec(text)) !== null) {
52→    // Push plain text before this match
53→    if (match.index > lastIndex) {
54→      nodes.push(text.slice(lastIndex, match.index));
55→    }
56→    if (match[2]) {
57→      // Bold: **text**
58→      nodes.push(<b key={key++}>{match[2]}</b>);
59→    } else if (match[3]) {
60→      // Code: `text`
61→      nodes.push(<code key={key++}>{match[3]}</code>);
62→    } else if (match[4]) {
63→      // Italic: *text*
64→      nodes.push(<em key={key++}>{match[4]}</em>);
65→    }
66→    lastIndex = match.index + match[0].length;
67→  }
68→
69→  // Push remaining plain text
70→  if (lastIndex < text.length) {
71→    nodes.push(text.slice(lastIndex));
72→  }
73→
74→  return <>{nodes}</>;
75→}
